import{_ as a,o as e,c as i,ag as s}from"./chunks/framework.CtWPcAmt.js";const g=JSON.parse('{"title":"第 12 章：建立自己的模板库","description":"哪些内容适合模板化、任务/检查清单/输出格式/案例四类模板、避免万能提示词、版本迭代；产出三个个人常用任务模板。","frontmatter":{"title":"第 12 章：建立自己的模板库","description":"哪些内容适合模板化、任务/检查清单/输出格式/案例四类模板、避免万能提示词、版本迭代；产出三个个人常用任务模板。","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/12-template-library.md","filePath":"guide/12-template-library.md","lastUpdated":null}'),l={name:"guide/12-template-library.md"};function n(r,t,d,o,h,p){return e(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="第-12-章-建立自己的模板库" tabindex="-1">第 12 章：建立自己的模板库 <a class="header-anchor" href="#第-12-章-建立自己的模板库" aria-label="Permalink to &quot;第 12 章：建立自己的模板库&quot;">​</a></h1><h2 id="本章解决什么问题" tabindex="-1">本章解决什么问题 <a class="header-anchor" href="#本章解决什么问题" aria-label="Permalink to &quot;本章解决什么问题&quot;">​</a></h2><p>同一类任务你已经做了三遍：写周报、整理会议记录、做对比表。每次都要重新打字、重新解释，烦。<strong>模板就是把「重复的部分」固化下来，只留「每次变化的部分」填空。</strong> 本章教你建三类模板（任务、检查清单、输出格式），并警告一个常见误区：<strong>模板不是万能提示词</strong>。产出：三个个人常用任务模板。</p><h2 id="从一个真实场景开始" tabindex="-1">从一个真实场景开始 <a class="header-anchor" href="#从一个真实场景开始" aria-label="Permalink to &quot;从一个真实场景开始&quot;">​</a></h2><p>对比两次写「周报」：</p><p><strong>每次重打</strong>：周五下午 4 点，打开 Agent，重新输入「帮我写周报，我这周做了……（写 200 字），格式要……」，Agent 每次理解的格式都略有不同，你还得反复修。</p><p><strong>用模板</strong>：<code>weekly-report.md</code> 模板里有固定结构——本周完成/下周计划/风险与求助/数据口径；你只填「本周 3 件事 + 1 个风险」，发一句话「用 weekly-report 模板整理我的周报，内容如下：……」。10 分钟搞定，格式永远一致。</p><p><strong>模板的本质：把「判断」从每次重复里抽出来，存成一次性的资产。</strong></p><h2 id="先说结论" tabindex="-1">先说结论 <a class="header-anchor" href="#先说结论" aria-label="Permalink to &quot;先说结论&quot;">​</a></h2><ol><li><strong>四类可模板化内容</strong>：任务卡（怎么描述）、检查清单（怎么验收）、输出格式（长什么样）、案例（怎么处理同类问题）；</li><li><strong>模板 = 固定结构 + 变量占位</strong>：结构一旦写好就稳定，变量每次填；</li><li><strong>判断是否模板化的标准</strong>：做第三遍时，停下来想想「前三遍哪部分是重复的？」重复的 → 模板；不重复的 → 变量；</li><li><strong>模板不是万能提示词</strong>：万能提示词是「一句话期望它全懂」，模板是「结构化的工作单」——后者才稳定可复用；</li><li><strong>模板要版本迭代</strong>：每次使用后标记「哪里不适用」，改一版，别怕改。</li></ol><h2 id="必要概念" tabindex="-1">必要概念 <a class="header-anchor" href="#必要概念" aria-label="Permalink to &quot;必要概念&quot;">​</a></h2><ul><li><strong>模板（Template）</strong>：带变量占位的结构化文档。白话解释：填空题试卷，题目固定，答案每次不同。</li><li><strong>变量（Variable）</strong>：模板中每次需要填写的部分，用占位符标出（如 <code>【本周完成】</code>）。</li><li><strong>版本（Version）</strong>：模板的迭代记录。至少保留「当前版」与「上次改了什么」。</li><li><strong>适用范围（Scope）</strong>：模板适用与不适用的任务类型。写清楚，避免硬套。</li></ul><h2 id="四类模板与写法" tabindex="-1">四类模板与写法 <a class="header-anchor" href="#四类模板与写法" aria-label="Permalink to &quot;四类模板与写法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模板类型</th><th>固定什么</th><th>变量什么</th><th>例子</th></tr></thead><tbody><tr><td><strong>任务卡模板</strong></td><td>六要素结构 + 你的常用口径</td><td>目标、材料、验收点</td><td>第 7 章任务卡 + 你的固定禁区</td></tr><tr><td><strong>检查清单模板</strong></td><td>验收项、常见错误</td><td>具体数字、文件</td><td>第 10 章验收清单</td></tr><tr><td><strong>输出格式模板</strong></td><td>标题层级、表格列、风格</td><td>内容</td><td>周报、会议纪要、对比表</td></tr><tr><td><strong>案例模板</strong></td><td>背景/任务/过程/验收结构</td><td>内容</td><td>第 6 篇案例结构</td></tr></tbody></table><h2 id="跟着做-创建你的前三个模板" tabindex="-1">跟着做：创建你的前三个模板 <a class="header-anchor" href="#跟着做-创建你的前三个模板" aria-label="Permalink to &quot;跟着做：创建你的前三个模板&quot;">​</a></h2><h3 id="第一步-盘点你的高频任务" tabindex="-1">第一步：盘点你的高频任务 <a class="header-anchor" href="#第一步-盘点你的高频任务" aria-label="Permalink to &quot;第一步：盘点你的高频任务&quot;">​</a></h3><p>从序章任务 + 最近一个月做过的事里，找出 3 个重复 ≥2 次的类型（如：整理材料、写总结、做对比）。</p><h3 id="第二步-抽「重复部分」" tabindex="-1">第二步：抽「重复部分」 <a class="header-anchor" href="#第二步-抽「重复部分」" aria-label="Permalink to &quot;第二步：抽「重复部分」&quot;">​</a></h3><p>对每个类型，回答：每次我都说一样的是什么？（结构、口径、禁区、格式）每次都在变的是什么？（具体内容）。</p><h3 id="第三步-写模板文件" tabindex="-1">第三步：写模板文件 <a class="header-anchor" href="#第三步-写模板文件" aria-label="Permalink to &quot;第三步：写模板文件&quot;">​</a></h3><p>用 <code>【变量】</code> 标出变量，固定部分写清楚。示例（输出格式模板）：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 【标题】</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">&gt; 生成日期：【日期】｜数据核验：【核验日期】｜来源：【材料路径】</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 结论（先给结论）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">【一句话结论】</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 对比</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| 维度 | 【项A】 | 【项B】 | 说明 |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">|---|---|---|---|</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| 【维度1】 | | | |</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 来源与限制</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">【材料清单 + 哪些未验证】</span></span></code></pre></div><h3 id="第四步-试用并迭代" tabindex="-1">第四步：试用并迭代 <a class="header-anchor" href="#第四步-试用并迭代" aria-label="Permalink to &quot;第四步：试用并迭代&quot;">​</a></h3><p>用模板跑一次真实任务，把「不适用」「没说清」的地方改掉，版本号 +1，写「本次改动」。</p><h2 id="一个完整示例" tabindex="-1">一个完整示例 <a class="header-anchor" href="#一个完整示例" aria-label="Permalink to &quot;一个完整示例&quot;">​</a></h2><p>本书的模板库（<code>templates/</code> 目录）就是范例：</p><ul><li><code>chapter-template.md</code>（章节模板）：固定「本章解决什么问题 → 真实场景 → 结论 → 概念 → 跟着做 → 示例 → 常见错误 → 安全提醒 → 练习 → 成果 → 小结」，变量是每章主题——你正在读的每一章都按它生成；</li><li><code>case-study-template.md</code>（案例模板）：固定案例结构（摘要→背景→需求→判断→任务卡→过程→问题→修正→验收→复盘→最小版本）；</li><li><code>agent-review-template.md</code>（产品体验模板）：十段式结构（一句话结论→版本地区→…→最终结论）。</li></ul><p><strong>这些模板让 20 多个章节保持结构统一</strong>——读者在任何一章都知道去哪里找「常见错误」或「安全提醒」，这就是模板的价值：一致性 + 可预期。</p><h2 id="常见错误与恢复方法" tabindex="-1">常见错误与恢复方法 <a class="header-anchor" href="#常见错误与恢复方法" aria-label="Permalink to &quot;常见错误与恢复方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>怎样修正</th></tr></thead><tbody><tr><td>模板越写越长，最后没人用</td><td>想把所有情况都装进去</td><td>砍到「80% 场景够用」，极端场景写进适用范围</td></tr><tr><td>硬套不合适的模板</td><td>没写适用范围</td><td>模板头部加「适用/不适用」</td></tr><tr><td>模板像万能提示词</td><td>变量没标清</td><td>变量用 <code>【】</code> 标出，固定部分写成「命令式」</td></tr><tr><td>改来改去没有记录</td><td>没版本管理</td><td>文件内加版本注释：v1.2 改了什么</td></tr><tr><td>模板成了僵化教条</td><td>过度模板化</td><td>记住：模板服务任务，任务不服务模板</td></tr></tbody></table><h2 id="安全提醒" tabindex="-1">安全提醒 <a class="header-anchor" href="#安全提醒" aria-label="Permalink to &quot;安全提醒&quot;">​</a></h2><ul><li>模板里不要写死敏感信息（密码、账号）；涉及时用变量占位「【提供于任务时】」；</li><li>任务卡模板里的禁区条款，是<strong>默认安全配置</strong>，不要为了省事删掉；</li><li>模板被多人/多项目共享时，先确认里面的口径适用于新场景。</li></ul><h2 id="本章练习" tabindex="-1">本章练习 <a class="header-anchor" href="#本章练习" aria-label="Permalink to &quot;本章练习&quot;">​</a></h2><p>30 分钟：按「跟着做」完成你的前三个模板（建议：任务卡模板、验收清单模板、你最常用输出格式模板），各跑一次试用并写版本记录。</p><h2 id="你应该带走的成果" tabindex="-1">你应该带走的成果 <a class="header-anchor" href="#你应该带走的成果" aria-label="Permalink to &quot;你应该带走的成果&quot;">​</a></h2><ul><li><strong>三个个人常用任务模板</strong>（任务卡 + 验收清单 + 输出格式），含变量标注与版本记录。</li></ul><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>做第三遍时，停下来抽重复部分——那是模板的原料；</li><li>四类模板：任务、检查清单、输出格式、案例；</li><li>模板 = 固定结构 + 变量占位，不是万能提示词；</li><li>写清适用范围，版本迭代；</li><li>模板是通往 Skill 的下一级台阶（第 13 章）。</li></ol>`,38)])])}const k=a(l,[["render",n]]);export{g as __pageData,k as default};
